<script>
const T=new URLSearchParams(location.search).get('t')||'';
const API=p=>`/webhook/${p}`;
const COLS={PEDIDOS:15,REQUISITOS:4,FORNECEDORES:4};
const STATUS=['PENDENTE','COMPLETO','EM COTAÇÃO','COMPRADO','CANCELADO'];
let D={PEDIDOS:null,REQUISITOS:null,FORNECEDORES:null};
function toast(m){const t=document.getElementById('toast');t.textContent=m;t.style.display='block';setTimeout(()=>t.style.display='none',2600)}
async function listar(aba){const r=await fetch(API('painel-listar')+`?t=${T}&aba=${aba}`);if(!r.ok)throw new Error('listar '+aba);return r.json()}
async function salvar(aba,row,vals){const r=await fetch(API('painel-salvar'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({t:T,aba,row_number:row,values:vals})});if(!r.ok)throw new Error('salvar');return r.json()}
async function anexar(aba,vals){const r=await fetch(API('painel-append'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({t:T,aba,values:vals})});if(!r.ok)throw new Error('anexar');return r.json()}
function aba(k){['ped','req','forn'].forEach(x=>{document.getElementById('v-'+x).style.display=x===k?'':'none';document.getElementById('tb-'+x).classList.toggle('on',x===k)})}
async function carregarTudo(){try{
 const[p,q,f]=await Promise.all([listar('PEDIDOS'),listar('REQUISITOS'),listar('FORNECEDORES')]);
 D.PEDIDOS=p;D.REQUISITOS=q;D.FORNECEDORES=f;desPed();desTab('REQUISITOS','v-req');desTab('FORNECEDORES','v-forn');
}catch(e){toast('Erro ao carregar: '+e.message)}}
function esc(s){return String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}
// ---------- PEDIDOS ----------
function desPed(){
 const el=document.getElementById('v-ped');const rows=D.PEDIDOS.rows;
 if(!rows.length){el.innerHTML='<p class="mut">Nenhum pedido na fila.</p>';return}
 const g={};rows.forEach(r=>{const k=r.values[0]||'?';(g[k]=g[k]||[]).push(r)});
 el.innerHTML=Object.keys(g).sort((a,b)=>Number(b)-Number(a)).map(num=>{
  const it=g[num];const h=it[0].values;const urg=(h[5]||'').toUpperCase()==='SIM';
  const podeCot=it.some(r=>(r.values[11]||'')==='COMPLETO');
  return `<div class="card"><div class="top">
   <span class="num">Pedido ${esc(num)}</span><span class="tag">${esc(h[1])}</span><span class="tag">${esc(h[4]||'obra —')}</span>
   <span class="tag">${esc(h[2])}</span>${urg?`<span class="tag urg">URGENTE${h[6]?': '+esc(h[6]):' (sem motivo)'}</span>`:''}
   <span style="flex:1"></span>${podeCot?`<button class="b" onclick="abrirCot('${num}')">📨 Enviar p/ cotação</button>`:''}
  </div><table><thead><tr><th>Item</th><th style="width:70px">Qt</th><th style="width:70px">Un</th><th>Categoria</th><th>Status</th><th>Pendências</th><th style="width:40px"></th></tr></thead><tbody>
  ${it.map(r=>trPed(r)).join('')}</tbody></table></div>`}).join('')}
function trPed(r){const v=r.values;const stc=(v[11]||'').replace(' ','.');
 return `<tr id="tr-${r.row_number}"><td>${esc(v[7])}</td><td>${esc(v[8])}</td><td>${esc(v[9])}</td><td>${esc(v[10])}</td>
 <td><span class="st ${stc}">${esc(v[11])}</span></td><td class="mut">${esc(v[12])}</td>
 <td><button class="ic" title="Editar" onclick="editPed(${r.row_number})">✎</button></td></tr>`}
function editPed(rn){const r=D.PEDIDOS.rows.find(x=>x.row_number===rn);const v=r.values;
 document.getElementById('tr-'+rn).innerHTML=`
 <td><input type=text id="e-item" value="${esc(v[7])}"></td><td><input type=text id="e-qt" value="${esc(v[8])}"></td>
 <td><input type=text id="e-un" value="${esc(v[9])}"></td><td><input type=text id="e-cat" value="${esc(v[10])}"></td>
 <td><select id="e-st">${STATUS.map(s=>`<option ${s===v[11]?'selected':''}>${s}</option>`).join('')}</select></td>
 <td><input type=text id="e-pend" value="${esc(v[12])}"></td>
 <td><button class="ic" title="Salvar" onclick="salvarPed(${rn})">💾</button></td>`}
async function salvarPed(rn){const r=D.PEDIDOS.rows.find(x=>x.row_number===rn);const v=[...r.values];
 v[7]=gv('e-item');v[8]=gv('e-qt');v[9]=gv('e-un');v[10]=gv('e-cat');v[11]=gv('e-st');v[12]=gv('e-pend');
 while(v.length<15)v.push('');
 try{await salvar('PEDIDOS',rn,v.slice(0,15));toast('Item salvo ✓');await carregarTudo()}catch(e){toast('Erro ao salvar')}}
function gv(id){return document.getElementById(id).value}
// ---------- COTAÇÃO ----------
function abrirCot(num){
 const it=D.PEDIDOS.rows.filter(r=>String(r.values[0])===String(num)&&(r.values[11]||'')==='COMPLETO');
 if(!it.length){toast('Nenhum item COMPLETO neste pedido');return}
 const obra=it[0].values[4]||'';const cats=[...new Set(it.map(r=>(r.values[10]||'GERAL').toUpperCase()))];
 const forn=D.FORNECEDORES.rows;
 const corpo=`Prezados, bom dia!\n\nGentileza cotar os materiais abaixo, posto obra ${obra||'(a confirmar)'}:\n\n`+it.map(r=>`• ${r.values[8]||''} ${r.values[9]||''} — ${r.values[7]}`).join('\n')+`\n\nFavor informar prazo de entrega e condições de pagamento.\n\nAtenciosamente,\nDepto. de Compras — Prisbel`;
 document.getElementById('modal-box').innerHTML=`<h3 style="margin-top:0">📨 Cotação — Pedido ${esc(num)}</h3>
 <p class="mut">Itens COMPLETOS incluídos: ${it.length}. Selecione os fornecedores:</p>
 <div class="lista-forn">${forn.map((f,i)=>{const cat=(f.values[0]||'').toUpperCase();const pre=cats.includes(cat)?'checked':'';
   return `<label><input type=checkbox class="ck-f" value="${esc(f.values[2])}" ${pre}> <b>${esc(f.values[1])}</b> <span class=mut>(${esc(f.values[0])} — ${esc(f.values[2])})</span></label>`}).join('')}</div>
 <p style="margin-bottom:4px"><b>Assunto:</b></p><input type=text id="cot-ass" value="Cotação — Pedido ${esc(num)}${obra?' — obra '+esc(obra):''}">
 <p style="margin-bottom:4px"><b>Mensagem:</b></p><textarea id="cot-corpo">${esc(corpo)}</textarea>
 <div style="display:flex;gap:10px;justify-content:flex-end;margin-top:12px">
 <button class="b sec" onclick="fecharModal()">Cancelar</button>
 <button class="b" onclick="enviarCot('${num}')">Enviar cotação</button></div>`;
 document.getElementById('modal').style.display='flex'}
function fecharModal(){document.getElementById('modal').style.display='none'}
async function enviarCot(num){
 const para=[...document.querySelectorAll('.ck-f:checked')].map(c=>c.value).filter(Boolean);
 if(!para.length){toast('Selecione ao menos um fornecedor');return}
 const it=D.PEDIDOS.rows.filter(r=>String(r.values[0])===String(num)&&(r.values[11]||'')==='COMPLETO');
 try{
  const r=await fetch(API('painel-cotacao'),{method:'POST',headers:{'Content-Type':'application/json'},
   body:JSON.stringify({t:T,para,assunto:gv('cot-ass'),corpo:gv('cot-corpo'),linhas:it.map(x=>x.row_number)})});
  if(!r.ok)throw new Error();fecharModal();toast(`Cotação enviada para ${para.length} fornecedor(es) ✓`);await carregarTudo();
 }catch(e){toast('Erro ao enviar cotação')}}
// ---------- TABELAS SIMPLES (REQUISITOS / FORNECEDORES) ----------
function desTab(aba,elId){
 const el=document.getElementById(elId);const d=D[aba];const nc=COLS[aba];
 el.innerHTML=`<div class="card"><table><thead><tr>${d.headers.map(h=>`<th>${esc(h)}</th>`).join('')}<th style="width:40px"></th></tr></thead><tbody>
 ${d.rows.map(r=>`<tr id="t${aba}-${r.row_number}">${r.values.slice(0,nc).map(c=>`<td>${esc(c)}</td>`).join('')}<td><button class="ic" onclick="editTab('${aba}',${r.row_number})">✎</button></td></tr>`).join('')}
 <tr class="addrow">${Array.from({length:nc}).map((_,i)=>`<td><input type=text id="n${aba}-${i}" placeholder="${esc(d.headers[i]||'')}"></td>`).join('')}
 <td><button class="ic" title="Adicionar" onclick="addTab('${aba}')">➕</button></td></tr></tbody></table></div>
 <p class="mut">Para excluir uma linha, edite-a e esvazie os campos — ou remova direto na planilha.</p>`}
function editTab(aba,rn){const d=D[aba];const nc=COLS[aba];const r=d.rows.find(x=>x.row_number===rn);
 document.getElementById(`t${aba}-${rn}`).innerHTML=r.values.slice(0,nc).map((c,i)=>`<td><input type=text id="e${aba}-${i}" value="${esc(c)}"></td>`).join('')+
 `<td><button class="ic" onclick="salvarTab('${aba}',${rn})">💾</button></td>`}
async function salvarTab(aba,rn){const nc=COLS[aba];const v=Array.from({length:nc},(_,i)=>gv(`e${aba}-${i}`));
 try{await salvar(aba,rn,v);toast('Salvo ✓');await carregarTudo()}catch(e){toast('Erro ao salvar')}}
async function addTab(aba){const nc=COLS[aba];const v=Array.from({length:nc},(_,i)=>gv(`n${aba}-${i}`));
 if(!v[0]){toast('Preencha ao menos a primeira coluna');return}
 try{await anexar(aba,v);toast('Linha adicionada ✓');await carregarTudo()}catch(e){toast('Erro ao adicionar')}}
carregarTudo();
</script></body></html>
